struct Booking {
    let apartmentTitle: String
    let checkInDay: Int
    let checkOutDay: Int
    let nights: Int
    let totalPrice: Int

    // Напиши здесь init? с параметрами apartmentTitle, pricePerNight, checkInDay, checkOutDay
    init?(apartmentTitle: String, pricePerNight: Int, checkInDay: Int, checkOutDay: Int) {
